import { getState, setState, reset, exportBackup, importBackup } from './store.js';
import { academy, minigames } from './data.js';
import { assessmentQuestions, answersFromForm, assessmentIsComplete, validateAssessment } from './assessment.js';
import { buildNutritionWeek, buildTrainingPlan, calculateNutritionTargets, combat, generateMissions, levelFromXp, rank, scoreAssessment, stageForDay, weeklySummary } from './engines.js';

const app = () => document.querySelector('#app');
const icon = name => `<i class="sys-icon i-${name}" aria-hidden="true"></i>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const meter = (value, color = 'blue') => `<div class="meter"><i class="${color}" style="width:${Math.min(100, Math.max(0, value))}%"></i></div>`;
const empty = (title, text) => `<div class="empty">${icon('sparkles')}<b>${title}</b><p>${text}</p></div>`;
const todayName = () => ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'][new Date().getDay()];
let timerId;

function mutate(update, event) {
  setState(state => {
    update(state);
    if (event) state.history.unshift({ id: crypto.randomUUID(), at: Date.now(), ...event });
    return state;
  });
}

function shell(content) {
  const state = getState();
  const nav = [['general', 'General', 'user-round'], ['training', 'Entrenamiento', 'dumbbell'], ['nutrition', 'Nutrición', 'utensils-crossed'], ['academy', 'Academia', 'graduation-cap'], ['more', 'Más', 'grid-2x2']];
  return `<div class="noise"></div>
    <header class="top"><button class="brand" data-route="general"><span class="brandmark">S</span><span>SYSTEM <b>// OWNER</b></span></button><nav>${nav.map(item => `<button class="${state.ui.route === item[0] ? 'active' : ''}" data-route="${item[0]}">${icon(item[2])}${item[1]}</button>`).join('')}</nav><div class="status"><span class="online"></span> LOCAL ACTIVE</div></header>
    <main>${content}</main>
    <nav class="bottom">${nav.map(item => `<button class="${state.ui.route === item[0] ? 'active' : ''}" data-route="${item[0]}">${icon(item[2])}<small>${item[1]}</small></button>`).join('')}</nav><div id="modal"></div>`;
}

function questionMarkup(question, index) {
  return `<fieldset class="assessment-card" data-question="${question.id}"><legend><span>${String(index + 1).padStart(2, '0')}</span><small>${question.section}</small>${question.text}</legend><div class="choice-grid ${question.multi ? 'multi' : ''}">${question.options.map(item => `<label class="choice"><input type="${question.multi ? 'checkbox' : 'radio'}" name="${question.id}" value="${esc(item.value)}"><span>${esc(item.label)}</span></label>`).join('')}</div>${question.multi ? '<small class="choice-help">Podés elegir más de una opción.</small>' : ''}</fieldset>`;
}

function onboarding() {
  const state = getState();
  const step = Math.min(5, Math.max(0, Number(sessionStorage.getItem('onStep') || 0)));
  if (step === 0) return `<section class="onboard cinematic"><div class="sigil">S</div><p class="eyebrow">PROTOCOLO DE DESPERTAR</p><h1>Tu vida.<br><em>Tu sistema.</em></h1><p>Vos elegís tu realidad y tus preferencias. El Sistema transforma esas respuestas en pruebas, rutina y alimentación.</p><button class="primary" data-on-next>INICIAR EVALUACIÓN ${icon('arrow-right')}</button><small>OWNER EDITION · TODO DESBLOQUEADO</small></section>`;
  if (step === 1) return `<section class="onboard"><div class="step">01 / 05 · IDENTIDAD</div><h2>Los datos que el cálculo necesita</h2><p>No vas a puntuarte a vos mismo. Estos datos se usan para estimar energía y adaptar la propuesta.</p><form id="identity" class="form-grid"><label>Nombre<input name="name" value="${esc(state.profile.name)}" required></label><label>Edad<input name="age" type="number" min="14" max="100" value="${state.profile.age}" required></label><label>Altura (cm)<input name="height" type="number" min="130" max="230" value="${state.profile.height}" required></label><label>Peso (kg)<input name="weight" type="number" min="35" max="300" step=".1" value="${state.profile.weight}" required></label><button class="primary wide">CONTINUAR</button></form></section>`;
  if (step === 2) return `<section class="onboard assessment-new"><div class="step">02 / 05 · CUESTIONARIO GUIADO</div><h2>30 decisiones concretas</h2><p>Elegí opciones sobre tu trabajo, entrenamiento, comidas y objetivos. No hay indicadores subjetivos.</p><form id="assessment">${assessmentQuestions.map(questionMarkup).join('')}<button class="primary assessment-submit">GENERAR MIS PRUEBAS Y PLAN</button></form></section>`;
  if (step === 3) return `<section class="onboard"><div class="step">03 / 05 · PRUEBAS DEL SISTEMA</div><h2>Ahora medimos evidencia real</h2><div class="test-protocol"><article><b>01 · Empuje</b><p>Realizá la versión de flexión elegida con técnica limpia. Detenete antes de perder la postura.</p></article><article><b>02 · Piernas</b><p>Sentadillas controladas durante 60 segundos, con la variante elegida.</p></article><article><b>03 · Core</b><p>Mantené la plancha elegida mientras puedas respirar y sostener posición.</p></article><article><b>04 · Intelecto</b><p>Respondé las secuencias sin calculadora. El resultado será evidencia, no XP.</p></article></div><form id="baseline" class="form-grid"><label>Flexiones correctas<input name="pushups" type="number" min="0" required></label><label>Sentadillas en 60 s<input name="squats" type="number" min="0" required></label><label>Plancha (segundos)<input name="plank" type="number" min="0" required></label><label>1 km caminando/corriendo (min)<input name="km" type="number" min="3" max="40" step=".1" required></label><fieldset class="wide mini-test"><legend>Secuencia: 2 · 6 · 12 · 20 · ?</legend><label><input type="radio" name="logic1" value="0" required> 26</label><label><input type="radio" name="logic1" value="1"> 30</label><label><input type="radio" name="logic1" value="0"> 32</label></fieldset><fieldset class="wide mini-test"><legend>Si todas las runas son señales y algunas señales son azules, ¿todas las runas son azules?</legend><label><input type="radio" name="logic2" value="1" required> No se puede afirmar</label><label><input type="radio" name="logic2" value="0"> Sí</label><label><input type="radio" name="logic2" value="0"> Ninguna</label></fieldset><button class="primary wide">ANALIZAR EVIDENCIA</button></form><p class="safety-note">Si una prueba genera dolor o no es segura para vos, registrá 0 y seguí una indicación profesional.</p></section>`;
  if (step === 4) {
    const recommendation = state.recommendations;
    const routine = { 'heavy-duty': 'Heavy Duty', hypertrophy: 'Hipertrofia', strength: 'Fuerza', 'full-body': 'Full Body' }[recommendation.routineType] || 'Full Body';
    const intellect = { logic: 'Lógica y patrones', memory: 'Memoria', focus: 'Atención y foco', planning: 'Planificación y decisiones' }[recommendation.intellect] || 'Lógica y patrones';
    const enabled = state.training.weeklyPlan.filter(day => day.enabled);
    return `<section class="onboard result-screen"><div class="step">04 / 05 · PROPUESTA DEL SISTEMA</div><h2>Tu base ya está calculada</h2><p>Esta es una propuesta inicial editable. Las calorías se calcularon con tus datos y objetivo; se ajustan luego con adherencia, peso, hambre y rendimiento.</p><div class="proposal-grid"><article class="panel"><small>ENERGÍA DIARIA</small><b>${recommendation.nutrition.calories}</b><span>kcal</span><p>${recommendation.nutrition.protein} g proteína · ${recommendation.nutrition.carbs} g carbos · ${recommendation.nutrition.fat} g grasas</p></article><article class="panel"><small>RUTINA PROPUESTA</small><b>${routine}</b><p>${enabled.map(day => day.day).join(' · ')}</p><span>${state.training.settings.duration} min por sesión</span></article><article class="panel"><small>PRIMER DESAFÍO INTELECTUAL</small><b>${intellect}</b><p>El Sistema te propondrá pruebas; tu habilidad sólo cambiará con evidencia.</p></article><article class="panel"><small>ALIMENTACIÓN</small><b>7 días</b><p>${state.nutrition.settings.count} comidas diarias basadas en tus preferencias.</p></article></div><button class="primary full" data-accept-plan>ACEPTAR BASE Y CONTINUAR</button></section>`;
  }
  return `<section class="onboard cinematic"><div class="rank-reveal">SISTEMA PERSONAL <b>GENERADO</b></div><h1>${esc(state.profile.name)},<br><em>tu plan está listo.</em></h1><div class="reveal-grid"><div><span>30</span> respuestas aplicadas</div><div><span>7</span> días planificados</div><div><span>20</span> habilidades con evidencia separada</div></div><button class="primary" data-finish>ENTRAR AL SISTEMA</button></section>`;
}

function hero() {
  const state = getState(), level = levelFromXp(state.xp);
  return `<section class="hero panel"><div class="avatar">${esc(state.profile.name.slice(0, 1))}</div><div class="identity"><p class="eyebrow">${esc(state.profile.title)}</p><h1>${esc(state.profile.name)}</h1><div class="level-line"><b>NIVEL ${level.level}</b><span>${level.current} / ${level.need} XP</span></div>${meter(level.percent)}</div><div class="hero-stats"><div>${icon('flame')}<b>${state.streak}</b><span>Racha</span></div><div>${icon('zap')}<b>+${state.history.filter(event => new Date(event.at).toDateString() === new Date().toDateString()).reduce((sum, event) => sum + (event.xp || 0), 0)}</b><span>XP hoy</span></div><div>${icon('calendar-days')}<b>${state.g30.day}</b><span>Día G30</span></div></div></section><section class="attribute-strip">${['Intelecto', 'Carisma', 'Rendimiento', 'Físico'].map((attribute, index) => { const skills = state.skills.filter(skill => skill.attr === attribute); const value = Math.round(skills.reduce((sum, skill) => sum + skill.score, 0) / Math.max(1, skills.length)); return `<div class="attr a${index}"><span>${attribute}</span><b>${value}</b>${meter(value, ['blue', 'violet', 'green', 'red'][index])}</div>`; }).join('')}</section>`;
}

function general() {
  const state = getState();
  const workout = state.training.weeklyPlan.find(day => day.day === todayName() && day.enabled) || state.training.weeklyPlan.find(day => day.enabled);
  const meals = state.nutrition.weeklyPlan[state.nutrition.selectedDay]?.meals || [];
  return `${hero()}<div class="section-title"><div><p class="eyebrow">PROTOCOLO DIARIO</p><h2>Qué tenés que hacer hoy</h2></div><span class="phase">DÍA ${state.g30.day} · ${stageForDay(state.g30.day).toUpperCase()}</span></div><div class="dashboard"><div class="main-stack">
    <section class="panel block"><div class="block-head"><div><span class="index">01</span><h3>Misiones del Sistema</h3></div><button class="ghost" data-recalibrate>${icon('rotate-ccw')} Recalibrar hoy</button></div>${state.missions.map(mission => `<article class="mission ${mission.status}"><button class="check" data-mission="${mission.id}">${mission.status === 'done' ? icon('check') : ''}</button><div><b>${esc(mission.title)}</b><p>${esc(mission.detail)}</p></div><span class="xp">+${mission.xp} XP</span><button class="dots" data-mission-na="${mission.id}">N/A</button></article>`).join('')}</section>
    <section class="panel block notes-block"><div class="block-head"><div><span class="index">02</span><h3>Cuaderno personal</h3><p>Ideas, sensaciones, proyectos y recordatorios.</p></div><button class="primary small" data-note-add>${icon('plus')} Nota</button></div><div class="notes-grid">${state.notes.length ? state.notes.sort((a, b) => Number(b.pinned) - Number(a.pinned) || b.updatedAt - a.updatedAt).map(note => `<article class="note-card ${note.pinned ? 'pinned' : ''}" data-note-edit="${note.id}"><button class="note-open" data-note-edit="${note.id}"><small>${note.pinned ? 'FIJADA · ' : ''}${new Date(note.updatedAt).toLocaleDateString('es-AR')}</small><b>${esc(note.title)}</b><p>${esc(note.body)}</p></button><button class="iconbtn danger" data-note-delete="${note.id}">${icon('trash-2')}</button></article>`).join('') : empty('Cuaderno vacío', 'Creá una nota para guardar algo importante.')}</div></section>
    <section class="panel block"><div class="block-head"><div><span class="index">03</span><h3>Hábitos G30</h3><p>Todos empiezan sin marcar. Tocá un hábito cuando lo cumplas.</p></div><button class="ghost" data-habit-add>${icon('plus')} Agregar</button></div><div class="habit-grid">${state.habits.map(habit => `<article class="habit ${habit.done ? 'done' : ''}"><button data-habit-toggle="${habit.id}"><span>${habit.done ? icon('check') : icon('circle')}</span><b>${esc(habit.name)}</b><small>${esc(habit.target)}</small></button><button class="iconbtn" data-habit-edit="${habit.id}">${icon('pencil')}</button>${habit.custom ? `<button class="remove" data-habit-delete="${habit.id}">${icon('x')}</button>` : ''}</article>`).join('')}</div></section></div>
    <aside class="side-stack"><section class="panel compact training-card"><p class="eyebrow">04 · ENTRENAMIENTO DE HOY</p>${workout?.exercises[0] ? `<img src="${workout.exercises[0].img}" alt="${esc(workout.exercises[0].name)}">` : ''}<h3>${esc(workout?.title || 'Recuperación')}</h3><p>${workout?.exercises.length || 0} ejercicios · ${state.training.settings.duration} min</p><button class="primary full" data-route="training">ABRIR PLAN ${icon('chevron-right')}</button></section><section class="panel compact"><p class="eyebrow">05 · ALIMENTACIÓN DE HOY</p><div class="macro"><b>${state.nutrition.settings.calories}</b><span>kcal calculadas</span></div>${meter(100, 'green')}<div class="mini-list">${meals.slice(0, 3).map(meal => `<span>${meal.slot}<b>${esc(meal.name)}</b></span>`).join('')}</div><button class="ghost full" data-route="nutrition">VER SEMANA</button></section><section class="panel compact"><p class="eyebrow">06 · CHECK-IN</p><form id="checkin"><label>Sueño <output>${state.checkin.sleep} h</output><input name="sleep" type="range" min="3" max="10" step=".5" value="${state.checkin.sleep}"></label><label>Energía <output>${state.checkin.energy}/5</output><input name="energy" type="range" min="1" max="5" value="${state.checkin.energy}"></label><label>Ánimo <output>${state.checkin.mood}/5</output><input name="mood" type="range" min="1" max="5" value="${state.checkin.mood}"></label><textarea name="note" placeholder="¿Qué necesitás recordar hoy?">${esc(state.checkin.note)}</textarea><button class="ghost full">GUARDAR CHECK-IN</button></form></section></aside></div>`;
}

function training() {
  const state = getState(), training = state.training;
  const planDay = training.weeklyPlan[training.selectedDay] || training.weeklyPlan.find(day => day.enabled);
  const exercise = planDay?.exercises[training.current];
  const types = [['heavy-duty', 'Heavy Duty'], ['hypertrophy', 'Hipertrofia'], ['strength', 'Fuerza'], ['full-body', 'Full Body']];
  return `<div class="page-head"><div><p class="eyebrow">ENTRENAMIENTO · PLAN ELEGIDO POR VOS</p><h1>Tu rutina semanal</h1><p>Elegí el método; el Sistema arma la base y después podés editar cada día.</p></div><button class="ghost" data-generate-routine>${icon('rotate-ccw')} Generar propuesta</button></div><section class="routine-selector panel"><span>TIPO DE RUTINA</span><div>${types.map(type => `<button class="${training.settings.type === type[0] ? 'active' : ''}" data-routine-type="${type[0]}">${type[1]}</button>`).join('')}</div></section><div class="week-strip training-week">${training.weeklyPlan.map((day, index) => `<button class="${training.selectedDay === index ? 'active' : ''} ${day.enabled ? '' : 'off'}" data-training-day="${index}"><small>${day.day.slice(0, 3)}</small><b>${day.enabled ? day.title.split('·')[0] : 'Descanso'}</b></button>`).join('')}</div>${!planDay?.enabled ? `<section class="panel rest-day">${icon('moon')}<h2>${planDay?.day}: recuperación</h2><p>Podés habilitar este día y editar su sesión.</p><button class="primary" data-edit-routine-day>EDITAR DÍA</button></section>` : `<div class="page-head session-head"><div><p class="eyebrow">${esc(planDay.day.toUpperCase())} · SESIÓN ${training.current + 1}/${planDay.exercises.length}</p><h2>${esc(planDay.title)}</h2></div><div class="row-actions"><button class="ghost" data-edit-routine-day>${icon('pencil')} Editar día</button><div class="timer"><span id="timer">00:00</span><button data-timer>${icon('play')}</button></div></div></div>${exercise ? `<div class="workout-layout"><section class="exercise-focus panel"><div class="exercise-visual"><img src="${exercise.img}" alt="${esc(exercise.name)}"><div class="counter">${training.current + 1} / ${planDay.exercises.length}</div></div><div class="exercise-info"><p class="eyebrow">${esc(exercise.target)}</p><h2>${esc(exercise.name)}</h2><p class="tech">${esc(exercise.tech)}</p><div class="prescription"><span><b>${exercise.setData.length}</b> series</span><span><b>${exercise.reps}</b> reps</span><span><b>${exercise.rest}s</b> descanso</span></div><div class="set-table"><header><span>Serie</span><span>KG</span><span>REPS</span><span>RPE</span><span>LISTO</span></header>${exercise.setData.map((set, index) => `<div class="set ${set.done ? 'done' : ''}"><b>${index + 1}</b><input type="number" value="${set.kg}" data-set="${index}" data-field="kg"><input type="number" value="${set.reps}" data-set="${index}" data-field="reps"><input type="number" min="1" max="10" value="${set.rpe}" data-set="${index}" data-field="rpe"><button class="check" data-set-done="${index}">${set.done ? icon('check') : ''}</button></div>`).join('')}</div><div class="row-actions"><button class="ghost" data-set-add>${icon('plus')} Serie</button><button class="ghost danger" data-set-remove>${icon('minus')} Serie</button></div><label>Notas de sesión<textarea data-training-note>${esc(exercise.notes || '')}</textarea></label><div class="workout-actions"><button class="ghost" data-ex-prev ${training.current === 0 ? 'disabled' : ''}>Anterior</button><button class="primary" data-ex-next>${training.current === planDay.exercises.length - 1 ? 'FINALIZAR SESIÓN' : 'SIGUIENTE EJERCICIO'}</button></div></div></section><aside class="workout-side"><section class="panel compact"><p class="eyebrow">PROGRESIÓN</p><p class="suggestion">${icon('trending-up')} Completá las series con técnica limpia y RPE ≤8 antes de subir carga.</p></section><section class="panel compact"><h3>Historial</h3><div class="record"><b>${training.history[0]?.volume || '—'}</b><span>Último volumen</span></div></section></aside></div>` : empty('Día sin ejercicios', 'Editá este día para sumar ejercicios.')}`}`;
}

function nutrition() {
  const state = getState(), nutrition = state.nutrition;
  const selected = nutrition.weeklyPlan[nutrition.selectedDay] || nutrition.weeklyPlan[0];
  const total = selected.meals.reduce((sum, meal) => ({ kcal: sum.kcal + meal.kcal, p: sum.p + meal.p, c: sum.c + meal.c, f: sum.f + meal.f }), { kcal: 0, p: 0, c: 0, f: 0 });
  return `<div class="page-head"><div><p class="eyebrow">NUTRICIÓN · SEMANA EDITABLE</p><h1>Plan de alimentación</h1><p>El Sistema calculó ${nutrition.settings.calories} kcal según tus datos y objetivo. Vos podés adaptar las comidas.</p></div><button class="ghost" data-shop-list>${icon('shopping-basket')} Lista semanal</button></div><div class="week-strip nutrition-week">${nutrition.weeklyPlan.map((day, index) => `<button class="${nutrition.selectedDay === index ? 'active' : ''}" data-nutrition-day="${index}"><small>${day.day.slice(0, 3)}</small><b>${day.day}</b></button>`).join('')}</div><div class="day-plan-head"><div><p class="eyebrow">${selected.day.toUpperCase()}</p><h2>Qué comés este día</h2></div><button class="ghost" data-edit-nutrition-day>${icon('pencil')} Editar día</button></div><section class="nutrition-summary panel"><div><span>ENERGÍA</span><b>${total.kcal} <small>/ ${nutrition.settings.calories} kcal</small></b>${meter(Math.round(total.kcal / nutrition.settings.calories * 100), 'green')}</div>${[['Proteína', total.p, nutrition.settings.protein], ['Carbos', total.c, nutrition.settings.carbs], ['Grasas', total.f, nutrition.settings.fat]].map(item => `<div><span>${item[0]}</span><b>${item[1]} <small>/ ${item[2]} g</small></b>${meter(Math.round(item[1] / item[2] * 100), 'green')}</div>`).join('')}</section><div class="meal-grid">${selected.meals.map((meal, mealIndex) => `<article class="meal panel ${nutrition.done.includes(meal.id) ? 'done' : ''}"><div class="meal-img"><img src="${meal.img}" alt="${esc(meal.name)}"><span>${meal.slot}</span><button data-favorite="${meal.id}">${icon('heart')}</button></div><div class="meal-body"><h3>${esc(meal.name)}</h3><div class="meal-macros"><span><b>${meal.kcal}</b> kcal</span><span><b>${meal.p}g</b> prot</span><span><b>${meal.c}g</b> carb</span><span><b>${meal.f}g</b> grasa</span></div><details><summary>Ingredientes y preparación ${icon('chevron-down')}</summary><h4>Ingredientes</h4><p>${esc(meal.ingredients)}</p><h4>Preparación</h4><p>${esc(meal.steps)}</p></details><div class="row-actions"><button class="ghost" data-edit-meal="${mealIndex}">${icon('pencil')} Editar</button><button class="primary" data-meal-done="${meal.id}">${nutrition.done.includes(meal.id) ? 'COMPLETADA' : 'MARCAR COMIDA'}</button></div></div></article>`).join('')}</div><section class="panel weekly-check"><div><p class="eyebrow">ADHERENCIA Y AJUSTE</p><h2>Señales para recalibrar</h2></div><label>Peso<input id="weight" type="number" step=".1" value="${nutrition.weight}" placeholder="kg"></label><label>Hambre <input id="hunger" type="range" min="1" max="5" value="${nutrition.hunger}"></label><label>Energía <input id="nut-energy" type="range" min="1" max="5" value="${nutrition.energy}"></label><button class="ghost" data-nut-save>GUARDAR</button></section>`;
}

function academyView() {
  const state = getState(), selectedId = sessionStorage.getItem('course');
  if (selectedId) { const course = academy.find(item => item.id === selectedId); return `<button class="back" data-course-back>${icon('arrow-left')} Volver a rutas</button><div class="course-head"><p class="eyebrow">RUTA → CURSO → LECCIONES → QUIZ</p><h1>${esc(course.title)}</h1></div><div class="lesson-layout"><section>${course.lessons.map((lesson, index) => `<article class="lesson panel"><span class="index">${String(index + 1).padStart(2, '0')}</span><div><h2>${esc(lesson[0])}</h2><p>${esc(lesson[1])}</p><button class="${state.academy.completed.includes(`${course.id}-${index}`) ? 'complete' : 'primary small'}" data-lesson="${course.id}-${index}">${state.academy.completed.includes(`${course.id}-${index}`) ? `${icon('check')} COMPLETADA` : 'COMPLETAR · +50 XP'}</button></div></article>`).join('')}</section><aside class="panel quiz"><p class="eyebrow">PRUEBA DE DOMINIO</p><h3>Quiz: ${esc(course.title)}</h3><p>¿Cuál es el principio central?</p><label><input type="radio" name="quiz" value="0"> Cambiar todo de golpe</label><label><input type="radio" name="quiz" value="1"> Diseñar práctica, medir y ajustar</label><label><input type="radio" name="quiz" value="0"> Esperar motivación perfecta</label><button class="primary full" data-quiz="${course.id}">EVALUAR</button></aside></div>`; }
  return `<div class="page-head"><div><p class="eyebrow">ACADEMIA DEL SISTEMA</p><h1>Rutas de aprendizaje</h1><p>Rutas → cursos → lecciones → quiz → progreso.</p></div></div><div class="path-grid">${academy.map((course, index) => { const done = course.lessons.filter((_, lessonIndex) => state.academy.completed.includes(`${course.id}-${lessonIndex}`)).length; return `<article class="path panel p${index}"><div class="path-icon">${icon(['shield', 'target', 'messages-square', 'dumbbell'][index])}</div><p class="eyebrow">RUTA ${String(index + 1).padStart(2, '0')}</p><h2>${esc(course.title)}</h2><p>${course.lessons.length} lecciones · 1 quiz</p>${meter(done / course.lessons.length * 100)}<button class="ghost full" data-course="${course.id}">ABRIR RUTA</button></article>`; }).join('')}</div>`;
}

function g30() { const state = getState(), pct = Math.round(state.g30.day / 30 * 100); return `<div class="page-head"><div><p class="eyebrow">CICLO DE TRANSFORMACIÓN</p><h1>G30 · Día ${state.g30.day}</h1><p>${esc(state.g30.goal)}</p></div><div class="g30-ring" style="--p:${pct}"><b>${pct}%</b><span>COMPLETO</span></div></div><section class="stage-map panel">${[['1–7', 'Diagnóstico y orden'], ['8–15', 'Construcción'], ['16–23', 'Intensificación'], ['24–30', 'Consolidación']].map(item => `<div class="${stageForDay(state.g30.day) === item[1] ? 'current' : ''}"><span>${item[0]}</span><b>${item[1]}</b></div>`).join('')}</section>`; }
function skills() { const state = getState(); return `<div class="page-head"><div><p class="eyebrow">CAPACIDAD REAL · NO XP</p><h1>Habilidades</h1><p>Sólo cambian con cuestionarios, pruebas y evidencia explícita.</p></div></div>${['Intelecto', 'Carisma', 'Rendimiento', 'Físico'].map((attribute, groupIndex) => `<section class="skill-group"><div class="group-title a${groupIndex}"><span>${attribute}</span></div><div class="skill-cards">${state.skills.filter(skill => skill.attr === attribute).map(skill => `<article class="panel"><div><h3>${skill.name}</h3><span class="rank">${rank(skill.score)}</span></div><b class="score">${Math.round(skill.score)}</b>${meter(skill.score, ['blue', 'violet', 'green', 'red'][groupIndex])}<footer><span>${skill.evidence} evidencias</span><span>Confianza: ${skill.confidence}</span><span>${skill.updated}</span></footer></article>`).join('')}</div></section>`).join('')}`; }
function progress() { const state = getState(), summary = weeklySummary(state); return `<div class="page-head"><div><p class="eyebrow">REPORTE SEMANAL</p><h1>Tu sistema está aprendiendo</h1></div></div><div class="kpi-grid"><div class="panel"><span>Misiones</span><b>${summary.completed}</b></div><div class="panel"><span>Hábitos</span><b>${summary.habitPct}%</b>${meter(summary.habitPct, 'green')}</div><div class="panel"><span>Entrenamientos</span><b>${summary.training}</b></div><div class="panel"><span>G30</span><b>${Math.round(state.g30.day / 30 * 100)}%</b></div></div><section class="panel block recommendation"><p class="eyebrow">RECOMENDACIÓN</p><h2>Una mejora, no diez</h2><p>${summary.recommendation}</p></section>`; }
function history() { const state = getState(); return `<div class="page-head"><div><p class="eyebrow">TRAZABILIDAD</p><h1>Historial</h1></div></div><section class="timeline">${state.history.length ? state.history.map(event => `<article><span class="timeline-dot"></span><div class="panel"><small>${new Date(event.at).toLocaleString('es-AR')}</small><h3>${esc(event.label || event.type)}</h3><p>${esc(event.detail || 'Acción registrada')}</p></div></article>`).join('') : empty('Todavía no hay eventos', 'Tus acciones importantes aparecerán acá.')}</section>`; }
function arena() { const state = getState(), arenaState = state.arena; return `<div class="arena-hero"><div><p class="eyebrow">SIMULACIÓN PVE</p><h1>Arena de las Sombras</h1><p>Esta sección será rediseñada en la próxima ronda. Sigue funcionando como simulación local.</p></div><div class="rating"><small>RATING</small><b>${arenaState.rating}</b><span>${arenaState.wins} V · ${arenaState.losses} D</span></div></div><div class="arena-layout"><section><div class="deck panel"><div class="deck-grid">${arenaState.deck.map(id => { const skill = arenaState.skills.find(item => item.id === id); return `<article><small>${skill.type}</small><b>${skill.name}</b><span>PODER ${skill.power}</span></article>`; }).join('')}</div><button class="primary full" data-battle>INICIAR SIMULACIÓN PVE</button></div><div class="games">${minigames.map((game, index) => `<button data-game="${index}"><span>${index + 1}</span><b>${game}</b></button>`).join('')}</div></section></div>`; }
function shop() { const state = getState(), items = [['Título', 'Cazador de Hábitos', 120], ['Marco', 'Nexo Cyan', 180], ['Skin', 'Panel Abisal', 250]]; return `<div class="page-head"><div><p class="eyebrow">SÓLO COSMÉTICOS</p><h1>Tienda</h1></div><div class="coins">${state.coins} monedas</div></div><div class="shop-grid">${items.map(item => `<article class="panel cosmetic"><div class="cosmetic-preview"><span>SYSTEM</span></div><small>${item[0]}</small><h2>${item[1]}</h2><button class="ghost full" data-buy="${item[2]}" data-item="${item[1]}">${item[2]} MONEDAS</button></article>`).join('')}</div>`; }
function profile() { const state = getState(); return `<div class="page-head"><div><p class="eyebrow">IDENTIDAD Y CONTROL</p><h1>Perfil</h1></div></div><div class="profile-layout"><section class="panel block"><form id="profile" class="form-grid"><label>Nombre<input name="name" value="${esc(state.profile.name)}"></label><label>Título<input name="title" value="${esc(state.profile.title)}"></label><label>Edad<input name="age" type="number" value="${state.profile.age}"></label><label>Altura<input name="height" type="number" value="${state.profile.height}"></label><label>Peso<input name="weight" type="number" step=".1" value="${state.profile.weight}"></label><label>Objetivo<input name="goal" value="${esc(state.profile.goal)}"></label><label class="wide">Contexto<textarea name="context">${esc(state.profile.context)}</textarea></label><button class="primary wide">GUARDAR</button></form></section><aside class="panel block account-actions"><button class="ghost full" data-export>Exportar backup JSON</button><label class="ghost full upload">Importar backup<input type="file" id="import" accept="application/json"></label><button class="ghost full" data-reassess>Repetir evaluación</button><button class="ghost danger full" data-reset>Resetear cuenta</button></aside></div>`; }
function assistant() { return `<div class="assistant-wrap"><section class="assistant-head"><div class="orb"></div><p class="eyebrow">ASISTENTE LOCAL</p><h1>¿Qué ajustamos?</h1><p>Siempre confirma antes de modificar tus datos.</p></section><section class="chat panel"><div class="message system">Puedo recalibrar misiones, cambiar la duración o agregar un hábito.</div><div class="quick">${['Entrenar 45 minutos', 'Recalibrar misiones', 'Agregar hábito meditar'].map(prompt => `<button data-prompt="${prompt}">${prompt}</button>`).join('')}</div><form id="assistant-form"><input name="command" placeholder="Escribí una orden…"><button class="primary">${icon('send')}</button></form></section></div>`; }

const moreItems = [['g30', 'G30', 'calendar-range', 'Ciclo y etapas'], ['skills', 'Habilidades', 'sparkles', 'Capacidad real'], ['progress', 'Progreso', 'chart-no-axes-combined', 'Reporte semanal'], ['history', 'Historial', 'history', 'Registro completo'], ['arena', 'Arena', 'swords', 'Simulaciones'], ['shop', 'Tienda', 'shopping-bag', 'Cosméticos'], ['profile', 'Perfil', 'settings', 'Datos y backup'], ['assistant', 'Asistente', 'message-circle', 'Ajustes guiados']];
function moreNav(active) { return `<aside class="more-tabs">${moreItems.map(item => `<button class="${active === item[0] ? 'active' : ''}" data-more="${item[0]}">${icon(item[2])}<span><b>${item[1]}</b><small>${item[3]}</small></span>${icon('chevron-right')}</button>`).join('')}</aside>`; }
function more() { const state = getState(), views = { g30, skills, progress, history, arena, shop, profile, assistant }; return `<div class="more-layout">${moreNav(state.ui.more)}<section class="more-content">${views[state.ui.more]()}</section></div>`; }

export function render() {
  const state = getState();
  if (!state.onboarded) { app().innerHTML = onboarding(); bind(); return; }
  const views = { general, training, nutrition, academy: academyView, more };
  app().innerHTML = shell((views[state.ui.route] || general)());
  bind();
}

function modal(html) { const target = document.querySelector('#modal'); if (!target) return; target.innerHTML = `<div class="overlay" data-close><div class="modal panel" onclick="event.stopPropagation()"><button class="modal-x" data-close>${icon('x')}</button>${html}</div></div>`; target.querySelectorAll('[data-close]').forEach(button => button.onclick = () => { target.innerHTML = ''; }); }
function toast(text) { const element = document.createElement('div'); element.className = 'toast'; element.textContent = text; document.body.append(element); setTimeout(() => element.remove(), 2600); }

function noteModal(id) {
  const note = id ? getState().notes.find(item => item.id === id) : null;
  modal(`<p class="eyebrow">${note ? 'EDITAR' : 'NUEVA'} NOTA</p><h2>Cuaderno personal</h2><form id="note-form" class="note-form"><label>Título<input name="title" value="${esc(note?.title || '')}" required></label><label>Contenido<textarea name="body" rows="10" required>${esc(note?.body || '')}</textarea></label><label class="pin-choice"><input type="checkbox" name="pinned" ${note?.pinned ? 'checked' : ''}> Fijar arriba</label><button class="primary full">GUARDAR NOTA</button></form>`);
  document.querySelector('#note-form').onsubmit = event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.target)); mutate(state => { if (note) Object.assign(state.notes.find(item => item.id === note.id), { title: data.title, body: data.body, pinned: Boolean(data.pinned), updatedAt: Date.now() }); else state.notes.push({ id: crypto.randomUUID(), title: data.title, body: data.body, pinned: Boolean(data.pinned), updatedAt: Date.now() }); }); document.querySelector('#modal').innerHTML = ''; };
}

function habitModal(id) {
  const habit = id ? getState().habits.find(item => item.id === id) : null;
  modal(`<p class="eyebrow">${habit ? 'EDITAR' : 'NUEVO'} HÁBITO</p><h2>Objetivo diario</h2><form id="habit-form" class="form-grid"><label>Nombre<input name="name" value="${esc(habit?.name || '')}" required></label><label>Objetivo<input name="target" value="${esc(habit?.target || '')}" required></label><button class="primary wide">GUARDAR</button></form>`);
  document.querySelector('#habit-form').onsubmit = event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.target)); mutate(state => { if (habit) Object.assign(state.habits.find(item => item.id === habit.id), data); else state.habits.push({ id: crypto.randomUUID(), ...data, baseline: 'Personal', active: true, done: false, custom: true }); }); document.querySelector('#modal').innerHTML = ''; };
}

function routineDayModal() {
  const state = getState(), day = state.training.weeklyPlan[state.training.selectedDay];
  const lines = day.exercises.map(exercise => `${exercise.name}|${exercise.setData.length}|${exercise.reps}|${exercise.rest}`).join('\n');
  modal(`<p class="eyebrow">EDITAR ${esc(day.day.toUpperCase())}</p><h2>Sesión semanal</h2><form id="routine-day-form" class="note-form"><label class="pin-choice"><input type="checkbox" name="enabled" ${day.enabled ? 'checked' : ''}> Día de entrenamiento activo</label><label>Nombre de la sesión<input name="title" value="${esc(day.title)}" required></label><label>Ejercicios <small>Una línea por ejercicio: nombre | series | reps | descanso</small><textarea name="exercises" rows="9">${esc(lines)}</textarea></label><button class="primary full">GUARDAR DÍA</button></form>`);
  document.querySelector('#routine-day-form').onsubmit = event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.target)); mutate(current => { const target = current.training.weeklyPlan[current.training.selectedDay]; target.enabled = Boolean(data.enabled); target.title = data.title; const previous = target.exercises; target.exercises = data.exercises.split('\n').map(line => line.trim()).filter(Boolean).map((line, index) => { const [name, setsRaw, repsRaw, restRaw] = line.split('|').map(value => value.trim()); const sets = Math.max(1, Number(setsRaw) || 3), reps = Math.max(1, Number(repsRaw) || 10), old = previous[index] || previous[0] || {}; return { ...old, id: old.id || crypto.randomUUID(), name, target: old.target || 'Personalizado', tech: old.tech || 'Usá técnica controlada y sin dolor.', img: old.img || 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=900&q=80', sets, reps, rest: Math.max(30, Number(restRaw) || 90), setData: Array.from({ length: sets }, (_, setIndex) => old.setData?.[setIndex] || { kg: 0, reps, rpe: 7, done: false }) }; }); current.training.current = 0; }); document.querySelector('#modal').innerHTML = ''; };
}

function mealModal(mealIndex) {
  const state = getState(), meal = state.nutrition.weeklyPlan[state.nutrition.selectedDay].meals[mealIndex];
  modal(`<p class="eyebrow">EDITAR COMIDA</p><h2>${esc(meal.slot)}</h2><form id="meal-form" class="form-grid"><label>Momento<input name="slot" value="${esc(meal.slot)}"></label><label>Nombre<input name="name" value="${esc(meal.name)}" required></label><label>Calorías<input name="kcal" type="number" value="${meal.kcal}"></label><label>Proteínas<input name="p" type="number" value="${meal.p}"></label><label>Carbohidratos<input name="c" type="number" value="${meal.c}"></label><label>Grasas<input name="f" type="number" value="${meal.f}"></label><label class="wide">Ingredientes<textarea name="ingredients">${esc(meal.ingredients)}</textarea></label><label class="wide">Preparación<textarea name="steps">${esc(meal.steps)}</textarea></label><button class="primary wide">GUARDAR COMIDA</button></form>`);
  document.querySelector('#meal-form').onsubmit = event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.target)); ['kcal', 'p', 'c', 'f'].forEach(key => data[key] = Number(data[key])); mutate(current => Object.assign(current.nutrition.weeklyPlan[current.nutrition.selectedDay].meals[mealIndex], data)); document.querySelector('#modal').innerHTML = ''; };
}

function nutritionDayModal() {
  const state = getState(), day = state.nutrition.weeklyPlan[state.nutrition.selectedDay];
  modal(`<p class="eyebrow">EDITAR ${esc(day.day.toUpperCase())}</p><h2>Elegí una comida</h2><p>Podés modificar nombre, cantidades, calorías, macros, ingredientes y preparación.</p><div class="day-meal-editor">${day.meals.map((meal, index) => `<button class="ghost full" data-pick-meal="${index}"><span>${esc(meal.slot)}</span><b>${esc(meal.name)}</b>${icon('chevron-right')}</button>`).join('')}</div>`);
  document.querySelectorAll('[data-pick-meal]').forEach(button => button.onclick = () => mealModal(Number(button.dataset.pickMeal)));
}

function finishWorkout() {
  const state = getState(), day = state.training.weeklyPlan[state.training.selectedDay], sets = day.exercises.flatMap(exercise => exercise.setData);
  const volume = sets.reduce((sum, set) => sum + set.kg * set.reps, 0), rpe = sets.length ? (sets.reduce((sum, set) => sum + set.rpe, 0) / sets.length).toFixed(1) : 0;
  modal(`<p class="eyebrow">SESIÓN COMPLETA</p><h2>Buen trabajo.</h2><div class="battle-result"><span>Volumen <b>${volume} kg</b></span><span>RPE medio <b>${rpe}</b></span><span>Series <b>${sets.filter(set => set.done).length}/${sets.length}</b></span></div><button class="primary full" id="save-workout">GUARDAR · +180 XP</button>`);
  document.querySelector('#save-workout').onclick = () => { mutate(current => { current.training.history.unshift({ at: Date.now(), day: day.day, volume, rpe }); current.training.current = 0; day.exercises.forEach(exercise => exercise.setData.forEach(set => set.done = false)); current.xp += 180; }, { type: 'training', label: 'Entrenamiento completado', xp: 180 }); document.querySelector('#modal').innerHTML = ''; };
}

function startGame(index) {
  const name = minigames[index], target = Math.floor(Math.random() * 9) + 1;
  modal(`<p class="eyebrow">MINIJUEGO</p><h2>${name}</h2><p>Tocá el número objetivo: <b>${target}</b></p><div class="game-board">${[1,2,3,4,5,6,7,8,9].sort(() => Math.random() - .5).map(number => `<button data-number="${number}">${number}</button>`).join('')}</div>`);
  const start = performance.now();
  document.querySelectorAll('[data-number]').forEach(button => button.onclick = () => { const ms = Math.round(performance.now() - start), ok = Number(button.dataset.number) === target; if (ok) mutate(state => state.coins += ms < 1200 ? 12 : 6, { type: 'arena', label: `${name}: ${ms} ms` }); document.querySelector('#modal').innerHTML = ''; toast(ok ? `Correcto · ${ms} ms` : 'Objetivo fallado'); });
}

function guardAssessmentSubmit(event) {
  const form = event.currentTarget;
  const validation = validateAssessment(answersFromForm(form));
  form.querySelectorAll('.assessment-card.invalid').forEach(card => card.classList.remove('invalid'));
  form.querySelector('.assessment-error')?.remove();
  if (validation.valid) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  const invalidIds = validation.missing.map(question => question.id);
  if (validation.dayMismatch && !invalidIds.includes('trainingDays')) invalidIds.push('trainingDays', 'weeklyFrequency');
  invalidIds.forEach(id => form.querySelector(`[data-question="${id}"]`)?.classList.add('invalid'));
  const firstMissing = validation.missing[0];
  const message = validation.dayMismatch
    ? `Elegiste ${validation.selectedDays} días, pero seleccionaste ${validation.weeklyFrequency} sesiones semanales.`
    : `Falta responder la pregunta ${assessmentQuestions.indexOf(firstMissing) + 1}: ${firstMissing.text}`;
  const notice = document.createElement('div');
  notice.className = 'assessment-error';
  notice.innerHTML = `<b>REVISÁ ESTA RESPUESTA</b><span>${esc(message)}</span>`;
  form.querySelector('.assessment-submit').before(notice);
  const firstInvalid = form.querySelector('.assessment-card.invalid');
  firstInvalid?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  toast(message);
}

function bind() {
  document.querySelector('#assessment')?.addEventListener('submit', guardAssessmentSubmit, true);
  document.querySelectorAll('[data-route]').forEach(button => button.onclick = () => { mutate(state => state.ui.route = button.dataset.route); window.scrollTo(0, 0); });
  document.querySelectorAll('[data-more]').forEach(button => button.onclick = () => { mutate(state => { state.ui.route = 'more'; state.ui.more = button.dataset.more; }); window.scrollTo(0, 0); });
  document.querySelector('[data-on-next]')?.addEventListener('click', () => { sessionStorage.setItem('onStep', 1); render(); });
  document.querySelector('#identity')?.addEventListener('submit', event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.target)); mutate(state => Object.assign(state.profile, data)); sessionStorage.setItem('onStep', 2); render(); });
  document.querySelector('#assessment')?.addEventListener('submit', event => { event.preventDefault(); const answers = answersFromForm(event.target); if (!assessmentIsComplete(answers)) return toast('Respondé todo y elegí al menos tantos días como sesiones semanales'); mutate(state => { state.onboardingAnswers = answers; const targets = calculateNutritionTargets(state.profile, answers); const weeklyPlan = buildTrainingPlan(answers); state.recommendations = { nutrition: targets, routineType: answers.routineType, intellect: answers.intellect }; state.training.weeklyPlan = weeklyPlan; state.training.selectedDay = Math.max(0, weeklyPlan.findIndex(day => day.enabled)); state.training.settings = { ...state.training.settings, type: answers.routineType, days: weeklyPlan.filter(day => day.enabled).length, duration: Number(answers.duration), equipment: answers.equipment, limitations: answers.limitations }; state.nutrition.settings = { ...state.nutrition.settings, ...targets, count: Number(answers.mealCount) }; state.nutrition.weeklyPlan = buildNutritionWeek(targets, answers); state.nutrition.preferences = { likes: [...(answers.proteins || []), ...(answers.carbs || []), ...(answers.produce || [])], dislikes: [answers.dislikes], exclusions: [answers.exclusions] }; const bases = scoreAssessment(answers); state.skills.forEach((skill, index) => { skill.score = Math.max(15, Math.min(85, bases[skill.attr] + (index % 5) * 2 - 4)); skill.evidence = 1; skill.confidence = 'Media'; skill.updated = 'Cuestionario inicial'; }); }); sessionStorage.setItem('onStep', 3); render(); });
  document.querySelector('#baseline')?.addEventListener('submit', event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.target)); mutate(state => { state.baseline = data; const physicalEvidence = Math.min(12, Number(data.pushups) / 5 + Number(data.squats) / 15 + Number(data.plank) / 30); state.skills.filter(skill => skill.attr === 'Físico').forEach((skill, index) => { skill.score = Math.min(90, Math.round(skill.score + physicalEvidence + index)); skill.evidence += 1; skill.confidence = 'Alta'; skill.updated = 'Pruebas físicas'; }); const logic = (Number(data.logic1) + Number(data.logic2)) / 2; state.skills.filter(skill => skill.attr === 'Intelecto').forEach(skill => { skill.score = Math.min(90, Math.round(skill.score + logic * 6)); skill.evidence += 1; skill.confidence = 'Media'; skill.updated = 'Prueba intelectual'; }); }); sessionStorage.setItem('onStep', 4); render(); });
  document.querySelector('[data-accept-plan]')?.addEventListener('click', () => { sessionStorage.setItem('onStep', 5); render(); });
  document.querySelector('[data-finish]')?.addEventListener('click', () => mutate(state => { state.onboarded = true; state.assessmentVersion = 2; }));

  document.querySelector('[data-recalibrate]')?.addEventListener('click', () => mutate(state => { const done = state.missions.filter(mission => mission.status === 'done'); state.missions = [...done, ...generateMissions(state).slice(0, 3 - done.length)]; }));
  document.querySelectorAll('[data-mission]').forEach(button => button.onclick = () => mutate(state => { const mission = state.missions.find(item => item.id === button.dataset.mission); mission.status = mission.status === 'done' ? 'open' : 'done'; if (mission.status === 'done') state.xp += mission.xp; }, { type: 'mission', label: 'Misión actualizada' }));
  document.querySelectorAll('[data-mission-na]').forEach(button => button.onclick = () => mutate(state => state.missions.find(item => item.id === button.dataset.missionNa).status = 'na'));
  document.querySelector('[data-note-add]')?.addEventListener('click', () => noteModal());
  document.querySelectorAll('[data-note-edit]').forEach(button => button.onclick = event => { event.stopPropagation(); noteModal(button.dataset.noteEdit); });
  document.querySelectorAll('[data-note-delete]').forEach(button => button.onclick = event => { event.stopPropagation(); modal(`<p class="eyebrow">CONFIRMAR</p><h2>Eliminar nota</h2><p>Esta acción no se puede deshacer.</p><button class="ghost danger full" id="confirm-note-delete">ELIMINAR</button>`); document.querySelector('#confirm-note-delete').onclick = () => { mutate(state => state.notes = state.notes.filter(note => note.id !== button.dataset.noteDelete)); document.querySelector('#modal').innerHTML = ''; }; });
  document.querySelectorAll('[data-habit-toggle]').forEach(button => button.onclick = () => mutate(state => { const habit = state.habits.find(item => item.id === button.dataset.habitToggle); habit.done = !habit.done; if (habit.done) state.xp += 25; }, { type: 'habit', label: 'Hábito actualizado' }));
  document.querySelector('[data-habit-add]')?.addEventListener('click', () => habitModal());
  document.querySelectorAll('[data-habit-edit]').forEach(button => button.onclick = () => habitModal(button.dataset.habitEdit));
  document.querySelectorAll('[data-habit-delete]').forEach(button => button.onclick = () => mutate(state => state.habits = state.habits.filter(habit => habit.id !== button.dataset.habitDelete)));
  document.querySelector('#checkin')?.addEventListener('submit', event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.target)); mutate(state => state.checkin = { ...data, sleep: Number(data.sleep), energy: Number(data.energy), mood: Number(data.mood) }, { type: 'checkin', label: 'Check-in diario' }); toast('Check-in guardado'); });

  document.querySelectorAll('[data-routine-type]').forEach(button => button.onclick = () => mutate(state => state.training.settings.type = button.dataset.routineType));
  document.querySelector('[data-generate-routine]')?.addEventListener('click', () => mutate(state => { const answers = { ...state.onboardingAnswers, routineType: state.training.settings.type, weeklyFrequency: String(state.training.settings.days) }; state.training.weeklyPlan = buildTrainingPlan(answers); state.training.selectedDay = Math.max(0, state.training.weeklyPlan.findIndex(day => day.enabled)); state.training.current = 0; }));
  document.querySelectorAll('[data-training-day]').forEach(button => button.onclick = () => mutate(state => { state.training.selectedDay = Number(button.dataset.trainingDay); state.training.current = 0; }));
  document.querySelector('[data-edit-routine-day]')?.addEventListener('click', routineDayModal);
  document.querySelectorAll('[data-set]').forEach(input => input.onchange = () => mutate(state => state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current].setData[Number(input.dataset.set)][input.dataset.field] = Number(input.value)));
  document.querySelectorAll('[data-set-done]').forEach(button => button.onclick = () => mutate(state => { const set = state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current].setData[Number(button.dataset.setDone)]; set.done = !set.done; }));
  document.querySelector('[data-set-add]')?.addEventListener('click', () => mutate(state => { const exercise = state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current]; exercise.setData.push({ kg: 0, reps: exercise.reps, rpe: 7, done: false }); }));
  document.querySelector('[data-set-remove]')?.addEventListener('click', () => mutate(state => { const sets = state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current].setData; if (sets.length > 1) sets.pop(); }));
  document.querySelector('[data-ex-prev]')?.addEventListener('click', () => mutate(state => state.training.current--));
  document.querySelector('[data-ex-next]')?.addEventListener('click', () => { const state = getState(), day = state.training.weeklyPlan[state.training.selectedDay]; if (state.training.current < day.exercises.length - 1) mutate(current => current.training.current++); else finishWorkout(); });
  document.querySelector('[data-training-note]')?.addEventListener('change', event => mutate(state => state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current].notes = event.target.value));
  document.querySelector('[data-timer]')?.addEventListener('click', () => { if (timerId) { clearInterval(timerId); timerId = null; return; } const start = Date.now(); timerId = setInterval(() => { const clock = document.querySelector('#timer'); if (!clock) return clearInterval(timerId); const seconds = Math.floor((Date.now() - start) / 1000); clock.textContent = `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`; }, 250); });

  document.querySelectorAll('[data-nutrition-day]').forEach(button => button.onclick = () => mutate(state => state.nutrition.selectedDay = Number(button.dataset.nutritionDay)));
  document.querySelector('[data-edit-nutrition-day]')?.addEventListener('click', nutritionDayModal);
  document.querySelectorAll('[data-edit-meal]').forEach(button => button.onclick = () => mealModal(Number(button.dataset.editMeal)));
  document.querySelectorAll('[data-meal-done]').forEach(button => button.onclick = () => mutate(state => { const id = button.dataset.mealDone; state.nutrition.done = state.nutrition.done.includes(id) ? state.nutrition.done.filter(item => item !== id) : [...state.nutrition.done, id]; }, { type: 'nutrition', label: 'Comida registrada' }));
  document.querySelectorAll('[data-favorite]').forEach(button => button.onclick = () => mutate(state => { const id = button.dataset.favorite; state.nutrition.favorites = state.nutrition.favorites.includes(id) ? state.nutrition.favorites.filter(item => item !== id) : [...state.nutrition.favorites, id]; }));
  document.querySelector('[data-shop-list]')?.addEventListener('click', () => modal(`<p class="eyebrow">LISTA SEMANAL</p><h2>Compras base</h2><div class="shopping-list">${['Proteínas elegidas', 'Arroz, avena, papas y pan integral', 'Frutas y vegetales de la semana', 'Aceite, condimentos y básicos'].map(item => `<label><input type="checkbox"> ${item}</label>`).join('')}</div>`));
  document.querySelector('[data-nut-save]')?.addEventListener('click', () => mutate(state => { state.nutrition.weight = document.querySelector('#weight').value; state.nutrition.hunger = Number(document.querySelector('#hunger').value); state.nutrition.energy = Number(document.querySelector('#nut-energy').value); }));

  document.querySelectorAll('[data-course]').forEach(button => button.onclick = () => { sessionStorage.setItem('course', button.dataset.course); render(); });
  document.querySelector('[data-course-back]')?.addEventListener('click', () => { sessionStorage.removeItem('course'); render(); });
  document.querySelectorAll('[data-lesson]').forEach(button => button.onclick = () => mutate(state => { if (!state.academy.completed.includes(button.dataset.lesson)) { state.academy.completed.push(button.dataset.lesson); state.xp += 50; } }, { type: 'lesson', label: 'Lección completada', xp: 50 }));
  document.querySelector('[data-quiz]')?.addEventListener('click', event => { const value = document.querySelector('input[name=quiz]:checked')?.value; if (value == null) return toast('Elegí una respuesta'); const score = value === '1' ? 100 : 0; mutate(state => { state.academy.quizScores[event.currentTarget.dataset.quiz] = score; if (score) state.xp += 100; }, { type: 'quiz', label: score ? 'Quiz aprobado' : 'Quiz a revisar', xp: score ? 100 : 0 }); toast(score ? 'Quiz aprobado' : 'Revisá la lección'); });
  document.querySelector('[data-battle]')?.addEventListener('click', () => { const state = getState(), power = state.arena.deck.reduce((sum, id) => sum + state.arena.skills.find(skill => skill.id === id).power, 0), result = combat(power, state.arena.rating, Math.random()); modal(`<p class="eyebrow">RESULTADO PVE</p><h2>${result.win ? 'VICTORIA' : 'DERROTA TÁCTICA'}</h2><button class="primary full" id="claim">REGISTRAR RESULTADO</button>`); document.querySelector('#claim').onclick = () => { mutate(current => { current.arena.rating = Math.max(0, current.arena.rating + result.ratingDelta); current.arena[result.win ? 'wins' : 'losses']++; current.coins += result.reward; }, { type: 'arena', label: 'Simulación PvE' }); document.querySelector('#modal').innerHTML = ''; }; });
  document.querySelectorAll('[data-game]').forEach(button => button.onclick = () => startGame(Number(button.dataset.game)));
  document.querySelectorAll('[data-buy]').forEach(button => button.onclick = () => { const price = Number(button.dataset.buy); if (getState().coins < price) return toast('Monedas insuficientes'); modal(`<p class="eyebrow">CONFIRMAR COMPRA</p><h2>${button.dataset.item}</h2><button class="primary full" id="confirm-buy">CANJEAR ${price}</button>`); document.querySelector('#confirm-buy').onclick = () => { mutate(state => state.coins -= price, { type: 'reward', label: `Cosmético: ${button.dataset.item}` }); document.querySelector('#modal').innerHTML = ''; }; });
  document.querySelector('#profile')?.addEventListener('submit', event => { event.preventDefault(); mutate(state => Object.assign(state.profile, Object.fromEntries(new FormData(event.target)))); toast('Perfil actualizado'); });
  document.querySelector('[data-export]')?.addEventListener('click', () => { const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([exportBackup()], { type: 'application/json' })); link.download = 'system-facu-backup.json'; link.click(); URL.revokeObjectURL(link.href); });
  document.querySelector('#import')?.addEventListener('change', async event => { try { importBackup(await event.target.files[0].text()); } catch { toast('Backup inválido'); } });
  document.querySelector('[data-reassess]')?.addEventListener('click', () => { sessionStorage.setItem('onStep', 1); mutate(state => state.onboarded = false); });
  document.querySelector('[data-reset]')?.addEventListener('click', () => modal(`<p class="eyebrow">CONFIRMACIÓN FUERTE</p><h2>Resetear cuenta</h2><p>Escribí <b>RESET FACU</b>.</p><input id="reset-word"><button class="ghost danger full" id="reset-confirm">ELIMINAR TODO</button>`));
  document.querySelector('#reset-confirm')?.addEventListener('click', () => { if (document.querySelector('#reset-word').value === 'RESET FACU') reset(); else toast('Confirmación incorrecta'); });
  document.querySelectorAll('[data-prompt]').forEach(button => button.onclick = () => { document.querySelector('#assistant-form input').value = button.dataset.prompt; document.querySelector('#assistant-form').requestSubmit(); });
  document.querySelector('#assistant-form')?.addEventListener('submit', event => { event.preventDefault(); const command = new FormData(event.target).get('command').toLowerCase(); if (command.includes('recalibr')) return modal(`<p class="eyebrow">CONFIRMAR</p><h2>Recalibrar misiones</h2><button class="primary full" id="assistant-confirm">CONFIRMAR</button>`), document.querySelector('#assistant-confirm').onclick = () => { mutate(state => state.missions = generateMissions(state)); document.querySelector('#modal').innerHTML = ''; }; toast('Puedo recalibrar misiones en esta versión.'); });
}
